const $=id=>document.getElementById(id), KEY='adnote-v1', fmt=n=>Math.round(n).toLocaleString('ko-KR'), pct=n=>n===null?'—':n.toLocaleString('ko-KR',{maximumFractionDigits:2})+'%', esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
