function parseCSV(text){text=text.replace(/^\uFEFF/,'');const first=text.split(/\r?\n/)[0],delimiter=first.includes('\t')?'\t':first.includes(';')&&!first.includes(',')?';':',';let rows=[],row=[],value='',quoted=false;for(let i=0;i<text.length;i++){const c=text[i];if(c==='"'){if(quoted&&text[i+1]==='"'){value+='"';i++}else if(quoted||value==='')quoted=!quoted;else throw Error('CSV 따옴표 형식이 잘못되었습니다.')}else if(c===delimiter&&!quoted){row.push(value);value=''}else if((c==='\n'||c==='\r')&&!quoted){if(c==='\r'&&text[i+1]==='\n')i++;row.push(value);if(row.some(v=>v.trim()))rows.push(row);row=[];value=''}else value+=c}if(quoted)throw Error('CSV에서 닫히지 않은 따옴표를 발견했습니다.');row.push(value);if(row.some(v=>v.trim()))rows.push(row);return rows}
