function normalizeHeader(value){return String(value).normalize('NFKC').toLowerCase().replace(/[\s_\-./()[\]{}%₩,]/g,'')}
function findHeaderIndex(headers,aliases,key){let best=-1,bestScore=0;headers.forEach((header,index)=>{const normalized=normalizeHeader(header);if(key==='clicks'&&/(클릭률|ctr|clickthroughrate|clickrate)/.test(normalized))return;if(key==='purchases'&&/(전환율|conversionrate)/.test(normalized))return;if(key==='spend'&&/(평균클릭비용|averagecost|avgcost|cpc)/.test(normalized))return;aliases.forEach((alias,rank)=>{const candidate=normalizeHeader(alias);let score=normalized===candidate?1000-rank:candidate.length>=3&&normalized.includes(candidate)?500+candidate.length-rank:normalized.length>=3&&candidate.includes(normalized)?300+normalized.length-rank:0;if(score>bestScore){best=index;bestScore=score}})});return best}
$('importButton').onclick=()=>{$('importDialog').showModal()};$('csvFile').onchange=async e=>{const f=e.target.files[0];staged=null;$('mapping').hidden=true;$('importError').textContent='';if(!f)return;try{if(f.size>10*1024*1024)throw Error('10MB 이하의 CSV 파일을 선택해 주세요.');let bytes=await f.arrayBuffer(),text;try{text=new TextDecoder('utf-8',{fatal:true}).decode(bytes)}catch{text=new TextDecoder('euc-kr').decode(bytes)}let parsed=parseCSV(text);if(parsed.length<2)throw Error('헤더와 최소 1행의 데이터가 필요합니다.');if(parsed.length>100001)throw Error('한 번에 최대 100,000행을 처리할 수 있습니다.');let headers=parsed[0].map(s=>s.trim()),guesses=fields.map(([key,,aliases])=>findHeaderIndex(headers,aliases,key));staged={headers,rows:parsed.slice(1),filename:f.name};$('fileInfo').textContent=`${f.name} · ${fmt(staged.rows.length)}행 · 열 ${guesses.filter(i=>i>=0).length}/${fields.length}개 자동 인식`;$('mapFields').innerHTML=fields.map(([key,label],fieldIndex)=>{const selected=guesses[fieldIndex];return `<label>${label}<select id="map-${key}"><option value="">열 선택${key==='campaign'?' (미선택 시 전체)':''}</option>${headers.map((h,i)=>`<option value="${i}" ${selected===i?'selected':''}>${esc(h||'이름 없는 열 '+(i+1))}</option>`).join('')}</select></label>`}).join('');$('mapping').hidden=false}catch(e){$('importError').textContent=e.message}};
function normalizeDate(s){s=s.trim().replace(/\s*년\s*/g,'-').replace(/\s*월\s*/g,'-').replace(/\s*일\s*/g,'').replace(/[./]/g,'-').replace(/-$/,'');if(/^\d{8}$/.test(s))s=s.slice(0,4)+'-'+s.slice(4,6)+'-'+s.slice(6);const m=s.match(/^(\d{4})-(\d{1,2})-(\d{1,2})$/);return m?m[1]+'-'+m[2].padStart(2,'0')+'-'+m[3].padStart(2,'0'):s}
function importRows(){if(!staged)throw Error('CSV 파일을 먼저 선택해 주세요.');const mapping=Object.fromEntries(fields.map(([k])=>[k,$('map-'+k).value]));for(const [k,label] of fields)if(k!=='campaign'&&mapping[k]==='')throw Error(label+'에 해당하는 열을 선택해 주세요.');const selected=Object.values(mapping).filter(v=>v!=='');if(new Set(selected).size!==selected.length)throw Error('각 지표에는 서로 다른 열을 연결해 주세요.');return staged.rows.map((row,i)=>{if(row.length!==staged.headers.length)throw Error((i+2)+'행: 열 개수가 헤더와 다릅니다.');const r={date:normalizeDate(row[Number(mapping.date)]),campaign:mapping.campaign===''?'전체':row[Number(mapping.campaign)].trim()||'미분류'};if(!validDate(r.date))throw Error((i+2)+'행: 일자를 확인해 주세요. 합계 행은 삭제해 주세요.');for(const [k,label] of fields.slice(2)){const raw=row[Number(mapping[k])].trim().replace(/[,₩원\s]/g,'');if(!/^\d+(\.\d+)?$/.test(raw))throw Error((i+2)+'행: '+label+'에 0 이상의 숫자가 필요합니다. 빈칸은 0으로 입력해 주세요.');r[k]=Number(raw);if(!Number.isFinite(r[k])||r[k]>1e15)throw Error((i+2)+'행: 수치가 너무 큽니다.');if(['purchases','clicks','impressions'].includes(k)&&!Number.isInteger(r[k]))throw Error((i+2)+'행: '+label+'는 정수로 입력해 주세요.')}if(r.clicks>r.impressions)throw Error((i+2)+'행: 클릭수가 노출수보다 큽니다. 열 연결을 확인해 주세요.');return r})}
function collapseRows(rows){const map=new Map();for(const row of rows){const key=row.date+'\u0000'+row.campaign;if(!map.has(key))map.set(key,{...row});else{const saved=map.get(key);for(const field of ['spend','revenue','purchases','clicks','impressions'])saved[field]+=row[field]}}return map}
function mergeRows(existing,incoming){const stored=collapseRows(existing),fresh=collapseRows(incoming),existingDates=new Set(existing.map(row=>row.date)),incomingDates=new Set([...fresh.values()].map(row=>row.date));for(const [key,row] of stored)if(incomingDates.has(row.date))stored.delete(key);for(const [key,row] of fresh)stored.set(key,row);const added=[...fresh.values()].filter(row=>!existingDates.has(row.date)).length,updated=fresh.size-added,refreshedDates=[...incomingDates].filter(date=>existingDates.has(date)).length;return {rows:[...stored.values()].sort((a,b)=>a.date.localeCompare(b.date)||a.campaign.localeCompare(b.campaign,'ko')),added,updated,fileRows:fresh.size,refreshedDates}}
$('confirmImport').onclick=()=>{try{const incoming=importRows(),existing=state.isSample?[]:state.rows,result=mergeRows(existing,incoming),wasSample=state.isSample;state={...state,rows:result.rows,notes:wasSample?[]:state.notes,isSample:false,filename:staged.filename,name:wasSample?'애드노트 검색광고 리포트':state.name,importHistory:[...(wasSample?[]:state.importHistory||[]),{filename:staged.filename,importedAt:new Date().toISOString(),fileRows:result.fileRows,added:result.added,updated:result.updated,refreshedDates:result.refreshedDates}].slice(-100)};persist();initialize();$('importDialog').close();$('csvFile').value='';staged=null;$('mapping').hidden=true;notify(`누적 저장 완료 · 새 데이터 ${fmt(result.added)}개 · 기존 날짜 ${fmt(result.refreshedDates)}일 갱신`)}catch(e){$('importError').textContent=e.message}};
initialize();
if(document.modelContext?.registerTool){try{Promise.resolve(document.modelContext.registerTool({name:'set_report_period',title:'보고서 기간 조회',description:'현재 보고서의 조회 기간을 변경하고 집계된 성과를 반환합니다.',inputSchema:{type:'object',properties:{start:{type:'string'},end:{type:'string'}},required:['start','end'],additionalProperties:false},annotations:{readOnlyHint:false},execute(input){if(!input||!validDate(input.start)||!validDate(input.end)||input.start>input.end)throw Error('유효한 YYYY-MM-DD 시작일과 종료일이 필요합니다.');$('startDate').value=input.start;$('endDate').value=input.end;render();return aggregate(filtered(input.start,input.end))}})).catch(()=>{})}catch{}}
